import puppeteer from 'puppeteer-core';
const url=process.env.TEST_URL,executablePath=process.env.CHROME_PATH;if(!url||!executablePath)throw new Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function waitFor(fn,timeout=30000,step=200){const end=Date.now()+timeout;while(Date.now()<end){try{if(await fn())return true}catch(e){}await sleep(step)}return false}
const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-first-run','--no-default-browser-check'],timeout:30000});
const context=await browser.createBrowserContext();const page=await context.newPage();const errors=[];
page.on('pageerror',e=>errors.push(String(e?.stack||e?.message||e)));page.on('console',m=>{if(m.text().startsWith('[connect]'))console.log(m.text());if(m.type()==='error'&&!/Failed to load resource:.*404/i.test(m.text()))errors.push('console: '+m.text())});
await page.evaluateOnNewDocument(()=>{try{localStorage.setItem('BombermanPlayerName','ScoreCI');localStorage.setItem('BombermanRatingV1','500');localStorage.removeItem('BombermanScoreV1Initialized');localStorage.removeItem('BombermanCharacterV1')}catch(e){}try{if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({scope:location.href})}catch(e){}});
try{
 await page.goto(url,{waitUntil:'domcontentloaded',timeout:20000});
 const ready=await waitFor(()=>page.evaluate(()=>!!(window.BomberCharacter&&document.getElementById('buildVersion123')?.textContent==='v0.12.3'&&window.BomberQOL?.bottomRightOpponent&&document.getElementById('mainCustomizeTile')&&window.gGameEngine?.menu)),30000,200);
 if(!ready)throw new Error('character/customize runtime did not finish startup');
 await page.evaluate(()=>{if(!gGameEngine.menu.views.length)gGameEngine.menu.show()});await sleep(300);
 const menu=await page.evaluate(()=>({version:document.getElementById('buildVersion123')?.textContent,panel:!!document.getElementById('characterPanel'),score:BomberCharacter.getRating(),tileDisplay:getComputedStyle(document.getElementById('mainCustomizeTile')).display,tileText:document.getElementById('mainCustomizeTile').innerText,canvasCards:gGameEngine.menu.views.filter(v=>v instanceof createjs.Container&&v.children?.some(c=>String(c.text||'').toLowerCase()==='character')).length,shapeX:gGameEngine.menu.views.filter(v=>v instanceof createjs.Shape&&v._listeners?.click?.length).map(v=>v.x)}));
 console.log('CHAR_BOOT',JSON.stringify(menu));if(menu.version!=='v0.12.3'||!menu.panel||menu.score!==0||menu.tileDisplay==='none'||!menu.tileText.includes('Customize')||!menu.tileText.includes('Score 0')||menu.canvasCards!==0)throw new Error('customize menu / zero score did not initialize');
 if(menu.shapeX.length>=2&&(menu.shapeX[0]!==0||menu.shapeX[1]!==0))throw new Error('Single/Online hit areas shifted');
 await page.click('#mainCustomizeTile');await sleep(120);
 const panel=await page.evaluate(()=>({hidden:document.getElementById('characterPanel').hidden,genders:document.querySelectorAll('[data-char-gender]').length,skins:document.querySelectorAll('[data-char-skin]').length,hats:document.querySelectorAll('[data-char-hat]').length,shoes:document.querySelectorAll('[data-char-shoes]').length,score:document.getElementById('characterPreviewRating')?.textContent}));
 console.log('CHAR_PANEL',JSON.stringify(panel));if(panel.hidden||panel.genders!==2||panel.skins!==5||panel.hats!==3||panel.shoes!==5||!panel.score.includes('Score 0'))throw new Error('character options missing');
 await page.click('#characterRandom');await sleep(60);const previewAlpha=await page.evaluate(()=>{const c=document.getElementById('characterPreview'),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let a=0;for(let i=3;i<d.length;i+=4)a+=d[i];return a});if(previewAlpha<=0)throw new Error('character preview blank');await page.click('#characterClose');
 await page.evaluate(()=>{if(B115.els?.name)B115.els.name.value='ScoreCI';B115.localName='ScoreCI';B115.kind='public';B115.setRole('host');B115.startSimulated()});await sleep(1000);
 const sim=await page.evaluate(()=>{const s=gGameEngine.simulatedOpponent;return{role:B115.role,name:B115.remoteName,rating:s?.rating,rank:s?.leaderboardRank,skill:s?.humanSkill,tier:s?.skillTier,x:s?.position.x,y:s?.position.y,appearance:s?.characterAppearance,playerScore:gGameEngine.players[0]?.rating,matchStatus:B115.els.matchStatus?.textContent,hud0:document.querySelector('.qol_stat_box[data-slot="0"]')?.getAttribute('data-rating'),hud3:document.querySelector('.qol_stat_box[data-slot="3"]')?.getAttribute('data-rating'),hudRank3:document.querySelector('.qol_stat_box[data-slot="3"]')?.getAttribute('data-rank'),low:BomberCharacter.skillFromRating(0),high:BomberCharacter.skillFromRating(950)}});
 console.log('SIM_PROFILE',JSON.stringify(sim));if(sim.role!=='simulated'||!sim.name||sim.rating<0||sim.rating>1000||!(sim.skill>0)||sim.x!==15||sim.y!==11||!sim.appearance||sim.playerScore!==0||sim.hud0!=='0'||sim.hud3!==String(sim.rating)||!sim.rank||sim.hudRank3!==String(sim.rank)||!(sim.high>sim.low)||!sim.matchStatus.includes('ScoreCI')||!sim.matchStatus.includes('(#'+sim.rank+')'))throw new Error('simulated profile/skill/score/rank/spawn invalid');
 await page.evaluate(()=>gGameEngine.gameOver('win'));await sleep(120);const win=await page.evaluate(()=>BomberCharacter.getRating());console.log('SCORE_WIN',win);if(win!==10)throw new Error('competitive win did not add 10');
 await page.evaluate(()=>{gGameEngine.restart()});await sleep(800);await page.evaluate(()=>gGameEngine.beginSpectating());await sleep(120);const loss=await page.evaluate(()=>BomberCharacter.getRating());console.log('SCORE_LOSS',loss);if(loss!==0)throw new Error('competitive loss did not subtract 10');
 await page.evaluate(()=>{B115.setRole('offline');BomberCharacter.setRating(100);gGameEngine.menu.setMode('single')});await sleep(160);await page.evaluate(()=>gGameEngine.gameOver('win'));await sleep(100);const single=await page.evaluate(()=>BomberCharacter.getRating());console.log('SINGLEPLAYER_SCORE',single);if(single!==100)throw new Error('single-player changed competitive score');
 await page.evaluate(()=>{B115.setRole('simulated');BomberCharacter.setRating(1000);gGameEngine.menu.setMode('simulated')});await sleep(180);await page.evaluate(()=>gGameEngine.gameOver('win'));await sleep(100);const max=await page.evaluate(()=>BomberCharacter.getRating());if(max!==1000)throw new Error('score exceeded 1000 max');
 if(errors.length)throw new Error('browser errors: '+errors.join(' | '));console.log('CHARACTER_RATING_SMOKE PASS');
}finally{await context.close().catch(()=>{});await browser.close().catch(()=>{})}
